<?php declare(strict_types=1);namespace StudPulse\Integrations;use StudPulse\Bars\{BarsJournalSchedule,BarsLesson,ProviderResult};use StudPulse\Database\DB;final class ScheduleSubgroups{public const SUBJECTS=['language'=>'Английский язык','physicsLab'=>'Лабораторные по физике','graphics'=>'Инженерная графика'];public static function forUser(ProviderResult$schedule,string$userId):ProviderResult{$row=DB::one('SELECT preferences FROM user_preferences WHERE user_id=?',[$userId]);$saved=json_decode($row['preferences']??'{}',true);return self::filter($schedule,$saved['subgroups']??[]);}public static function options(ProviderResult$schedule):array{$variants=self::variants($schedule->items);$items=[];foreach(self::SUBJECTS as$key=>$title){$choices=[];foreach($variants as[$lesson,$subject,$id,$label]){if($subject!==$key){continue;}$choices[$id]??=['id'=>$id,'label'=>$label,'teachers'=>[]];if(self::hasTeacher($lesson['teacher_name']??'')&&!in_array($lesson['teacher_name'],$choices[$id]['teachers'],true)){$choices[$id]['teachers'][]=$lesson['teacher_name'];}}if(array_filter($choices,static fn(array$choice):bool=>$choice['id'][0]==='0')){$choices=array_filter($choices,static fn(array$choice):bool=>$choice['id'][0]==='0');}uasort($choices,static fn(array$a,array$b):int=>strnatcasecmp($a['label'],$b['label']));$items[]=['id'=>$key,'title'=>$title,'choices'=>array_values($choices)];}return['group'=>self::group($schedule),'items'=>$items];}public static function filter(ProviderResult$schedule,array$selection):ProviderResult{if(($selection['group']??'')!==self::group($schedule)){return$schedule;}$excluded=[];foreach(self::variants($schedule->items)as[$lesson,$key,$id]){if(!empty($selection[$key])&&$selection[$key][0]===$id[0]&&$selection[$key]!==$id){$excluded[$lesson['id']]=true;}}$items=array_values(array_filter($schedule->items,static fn(array$lesson):bool=>!isset($excluded[$lesson['id']])));return new ProviderResult($items,$schedule->source,$schedule->observedAt,$schedule->fixture,$schedule->details);}public static function combineParallel(ProviderResult$schedule,bool$preserveMaterials=false):ProviderResult{$items=[];$slots=[];foreach($schedule->items as$lesson){$title=mb_strtolower(trim($lesson['subject_title']));$type=mb_strtolower(trim($lesson['class_type']));$subject=self::subject($title,$type);$key=BarsLesson::subjectKey($title);$shared=BarsLesson::isSharedJournalSubject($key);if(($subject===null&&!$shared)||$lesson['status']==='cancelled'){$items[]=$lesson;continue;}$slot=$shared?$key.'|'.$lesson['start_at']:implode('|',[$title,$subject==='physicsLab'?$subject:$type,$lesson['start_at']]);if($preserveMaterials&&isset($lesson['libraryRef']))$slot.='|'.$lesson['libraryRef'];if(!isset($slots[$slot])){$slots[$slot]=count($items);$items[]=$lesson;continue;}$index=$slots[$slot];$previous=$items[$index];$sport=$key==='спортивные секции';$preferSection=$sport&&BarsLesson::titleKey($lesson['subject_title'])===$key;$previousSection=$sport&&BarsLesson::titleKey($previous['subject_title'])===$key;$priority=[$preferSection,$shared&&BarsJournalSchedule::canWriteType($lesson['class_type'])];$previousPriority=[$previousSection,$shared&&BarsJournalSchedule::canWriteType($previous['class_type'])];$useLesson=$priority!==$previousPriority?$priority>$previousPriority:strcmp($lesson['id'],$previous['id'])<0;$combined=$useLesson?$lesson:$previous;if(($previous['libraryRef']??null)!==($lesson['libraryRef']??null))unset($combined['libraryRef']);foreach(['teacher_name','official_room_code','subgroup_name']as$field){if(($previous[$field]??null)!==($lesson[$field]??null)){$combined[$field]='';}}$items[$index]=$combined;}return new ProviderResult($items,$schedule->source,$schedule->observedAt,$schedule->fixture,$schedule->details);}public static function subject(string$title,string$type):?string{return match(true){preg_match('/английск|иностранн/u',$title)===1=>'language',str_contains($title,'физик')&&preg_match('/лаборат|^лаб(?:[.\s]|$)/u',$type)===1=>'physicsLab',preg_match('/инженерн.*график|черчени/u',$title)===1=>'graphics',default=>null,};}public static function groupKey(string$code):string{return hash('sha256',mb_strtolower(trim($code)));}private static function group(ProviderResult$schedule):string{return self::groupKey($schedule->details['group']??'');}public static function lessonTracks(ProviderResult$schedule):array{$tracks=[];foreach(self::variants($schedule->items)as[$lesson,$key,$id,$label]){$tracks[$lesson['id']]=['subject'=>$key,'variant'=>$id,'teacher'=>self::folderLabel($label,[$lesson['teacher_name']??''])];}return$tracks;}public static function folderLabel(string$label,array$teachers):string{$names=array_values(array_filter(array_unique($teachers),static fn(string$name):bool=>self::hasTeacher($name)&&$name!==$label));return mb_substr(implode(' · ',[...$names,$label]),0,180);}public static function hasTeacher(string$name):bool{return$name!==''&&!preg_match('/^!|не\s+определен[а-яё]*|ваканси/iu',$name);}private static function variants(array$lessons):array{$labelled=[];$parallel=[];foreach($lessons as$lesson){$title=mb_strtolower($lesson['subject_title']);$type=mb_strtolower($lesson['class_type']);$key=self::subject($title,$type);if($key===null||($lesson['status']??'')==='cancelled'){continue;}$subgroup=trim($lesson['subgroup_name']??'');if($subgroup!==''&&!preg_match('/^(?:0|[-—–]|все|вся группа)$/uiD',$subgroup)){$label=ctype_digit($subgroup)?'Подгруппа '.$subgroup:$subgroup;$id='0'.substr(hash('sha256',mb_strtolower($subgroup)),1);$labelled[]=[$lesson,$key,$id,$label];}elseif(self::hasTeacher($lesson['teacher_name']??'')&&!str_contains($type,'лекци')){$slot=implode('|',[$key,$title,$type,$lesson['start_at']]);$id='1'.substr(hash('sha256',mb_strtolower($lesson['teacher_name'])),1);$parallel[$slot][$id][]=[$lesson,$key,$id,$lesson['teacher_name']];}}foreach($parallel as$slot){if(count($slot)>1){foreach($slot as$rows){array_push($labelled,...$rows);}}}return$labelled;}}